arguments.command:
cd /app; git checkout tests/deliver_test.sh
sed -i '$d' tests/deliver_test.sh
cat >> tests/deliver_test.sh <<'E'
# ADR-0009: 4 attempts, waits 3^i (3, 9, 27 s); the count comes from RELAY_ATTEMPTS (docs/runbook.md).
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "default plan"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "RELAY_ATTEMPTS=6 plan"; fail=1; }
[ "$(RELAY_RETRY_MAX=6 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RELAY_RETRY_MAX is not read (CHANGELOG 1.9.0)"; fail=1; }
exit $fail
E
bash tests/deliver_test.sh; echo exit=$?

